const KEY='farm-manager-v1';
const fresh=()=>({stock:[],sales:[],health:[],expenses:[],workers:[]});
let db;try{db=JSON.parse(localStorage.getItem(KEY))||fresh()}catch{db=fresh();alert('Saved records could not be read. Restore a backup before adding new records.')}
let page='Overview',action='';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('en-ZM',{style:'currency',currency:'ZMW',maximumFractionDigits:2}).format(n),today=()=>new Date().toLocaleDateString('en-CA'),sum=(a,f)=>a.reduce((s,r)=>s+Number(r[f]||0),0);
const pages=['Overview','Sales','Stock','Animal health','Expenses','Workers'],icons=['◫','↗','▦','♡','↙','♧'];
$('nav').innerHTML=pages.map((p,i)=>`<a href="#${p}"><span>${icons[i]}</span>${p}</a>`).join('');
$('#date').textContent=new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
function status(){$('#status').textContent=navigator.onLine?'● Online · device storage':'● Offline · device storage'}status();addEventListener('online',status);addEventListener('offline',status);
function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));db=next;render();return true}catch{$('#error').textContent='Unable to save. Device storage may be full. Export a backup.';return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}
function empty(title,body){return `<div class="empty"><strong>${title}</strong>${body}</div>`}
function table(headers,rows){return rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty('No records yet','Use the button above to add your first record.')}
function row(c){return '<tr>'+c.map(v=>`<td>${v}</td>`).join('')+'</tr>'}
function panel(title,body,sub=''){return `<div class="panel"><div class="panel-head"><h2>${title}</h2><small>${sub}</small></div>${body}</div>`}
const verbs={Overview:'Record a sale',Sales:'Record a sale',Stock:'Add stock item','Animal health':'Record animal care',Expenses:'Add expense',Workers:'Add worker'};
function render(){page=decodeURIComponent(location.hash.slice(1))||'Overview';if(!pages.includes(page))page='Overview';$('nav').querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.textContent.endsWith(page)));$('#title').textContent=page==='Overview'?'Farm overview':page;$('#subtitle').textContent={Overview:'A little clarity for every day on the farm.',Sales:'From the field to your customers. Every sale accounted for.',Stock:'Know what you have, and what needs topping up.','Animal health':'Care records for every herd and flock.',Expenses:'Keep track of what goes into your farm.',Workers:'The people who keep your farm growing.'}[page];$('#add').textContent='+ '+verbs[page];let html='';
if(page==='Overview'){let low=db.stock.filter(s=>s.qty<=s.min),due=db.health.filter(h=>h.due&&h.due<=today()&&!h.done);html=`<div class="cards">${[['Sales recorded',money(sum(db.sales,'total')),'All recorded sales'],['Expenses incurred',money(sum(db.expenses,'amount')),'Includes recorded wages'],['Customers owe',money(sum(db.sales,'total')-sum(db.sales,'paid')),'Outstanding sales balances'],['Low stock items',low.length,'At or below your stock minimum']].map(a=>`<div class="card"><div class="label">${a[0]}</div><div class="number">${a[1]}</div><small>${a[2]}</small></div>`).join('')}</div><div class="grid">${panel('Recent sales',db.sales.length?db.sales.slice(-5).reverse().map(s=>`<div class="row"><div>${esc(s.product)}<small>${esc(s.customer||'Walk-in customer')} · ${esc(s.date)}</small></div><div>${money(s.total)}<small>${s.paid<s.total?'Balance '+money(s.total-s.paid):'Paid in full'}</small></div></div>`).join(''):empty('Your next sale starts here','Record produce, livestock, and other farm sales.'),'Latest activity')}${panel('Needs your attention',low.length+due.length?[...low.map(s=>`<div class="row"><div>${esc(s.name)}<small>${s.qty} ${esc(s.unit)} remaining</small></div><span class="pill">Low stock</span></div>`),...due.map(h=>`<div class="row"><div>${esc(h.animal)}<small>${esc(h.treatment)} · ${esc(h.due)}</small></div><span class="pill">Care due</span></div>`)].join(''):empty('A clear day ahead','Low stock and due animal care will appear here.'))}</div>${panel('Make a quick entry',`<div class="quick">${['sale','expense','health','movement'].map((a,i)=>`<button data-action="${a}">${['+ Record sale','+ Add expense','+ Animal care','+ Stock movement'][i]}</button>`).join('')}</div>`)}<div class="helper">Your farm includes goats, sheep, chickens, ducks, turkeys and cattle. Add crops and supplies in Stock as you need them.</div>`}
else if(page==='Stock')html=panel('Stock register',`<div class="quick"><button data-action="movement">+ Receive or use stock</button></div>`+table(['Item','Category','Available','Minimum'],db.stock.map(s=>row([esc(s.name),esc(s.category),`${s.qty} ${esc(s.unit)}`,`${s.min} ${esc(s.unit)}`]))));
else if(page==='Sales')html=panel('Sales register',table(['Date','Item / customer','Quantity','Sale value','Balance',''],db.sales.map(s=>row([esc(s.date),`${esc(s.product)}<br><small>${esc(s.customer||'Walk-in')}</small>`,s.qty,money(s.total),money(s.total-s.paid),s.paid<s.total?`<button class="text" data-pay="${s.id}">Add payment</button>`:'Paid']))));
else if(page==='Expenses')html=panel('Expense register',table(['Date','Description','Category','Amount','Paid','Balance'],db.expenses.map(e=>row([esc(e.date),esc(e.description),esc(e.category),money(e.amount),money(e.paid),e.paid<e.amount?`${money(e.amount-e.paid)} <button class="text" data-expay="${e.id}">Pay</button>`:money(0)]))));
else if(page==='Animal health')html=panel('Care register',table(['Animal / group','Species','Care given','Date','Next care',''],db.health.map(h=>row([esc(h.animal),esc(h.species),`${esc(h.treatment)}<br><small>${esc(h.notes)}</small>`,esc(h.date),esc(h.due||'—'),h.due?(h.done?'Completed':`<button class="text" data-done="${h.id}">Mark follow-up done</button>`):'—']))));
else html=panel('Workers',table(['Name','Role / phone','Task','Attendance','Wages'],db.workers.map(w=>row([esc(w.name),`${esc(w.role)}<br><small>${esc(w.phone)}</small>`,`${esc(w.task||'No task assigned')}<br><button class="text" data-task="${w.id}">Update task</button>`,`${(w.attendance||[]).length} days<br><button class="text" data-attend="${w.id}">Mark present today</button>`,`<button class="text" data-wage="${w.id}">Record wages</button>`]))));$('#content').innerHTML=html}
function input(name,label,type='text',value='',attrs=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs} required></label>`}
function select(name,label,opts){return `<label>${label}<select name="${name}" required>${opts.map(x=>{let a=Array.isArray(x)?x:[x,x];return `<option value="${esc(a[0])}">${esc(a[1])}</option>`}).join('')}</select></label>`}
const amount=(name,label,value='')=>input(name,label,'number',value,'min="0" step="0.01"');
let target='';
function open(a,id=''){action=a;target=id;$('#error').textContent='';let f='',title='';const date=()=>input('date','Date','date',today()),stocks=()=>select('stock','Stock item',db.stock.map(s=>[s.id,`${s.name} (${s.qty} ${s.unit})`]));
if(a==='stock'){title='Add a stock item';f=input('name','Item name')+select('category','Category',['Crop','Livestock','Feed','Medicine','Seed','Fertilizer','Other'])+select('unit','Unit',['kg','bag','crate','bunch','head','bird','litre','bottle','item'])+amount('qty','Opening quantity',0)+amount('min','Low stock threshold',0)}
if(a==='sale'){if(!db.stock.length){toast('Add a stock item before recording a sale.');location.hash='Stock';return}title='Record a sale';f=date()+stocks()+amount('qty','Quantity sold')+amount('price','Price per unit (ZMW)')+amount('paid','Payment received (ZMW)',0)+input('customer','Customer name','text','Walk-in')}
if(a==='movement'){if(!db.stock.length){toast('Add a stock item first.');location.hash='Stock';return}title='Receive or use stock';f=stocks()+select('direction','Movement',['Received','Used','Spoiled'])+amount('qty','Quantity')+input('reason','Reason / reference')}
if(a==='expense'||a==='wage'){title=a==='wage'?'Record wages':'Add an expense';f=date()+input('description','Description','text',a==='wage'?'Wages — '+db.workers.find(w=>w.id===id).name:'')+(a==='expense'?select('category','Category',['Feed','Seeds / fertilizer','Veterinary','Transport','Fuel','Repairs','Wages','Other']):'')+amount('amount','Total amount (ZMW)')+amount('paid','Amount paid (ZMW)',0)}
if(a==='health'){title='Record animal care';f=date()+input('animal','Animal tag / group name')+select('species','Species',['Goat','Sheep','Chicken','Duck','Turkey','Cattle'])+input('treatment','Treatment / vaccination / care')+`<label>Notes<textarea name="notes" placeholder="Medicine, dose given, vet, observations"></textarea></label><label>Next care date (optional)<input name="due" type="date"></label>`}
if(a==='worker'){title='Add a worker';f=input('name','Full name')+input('role','Role')+`<label>Phone (optional)<input name="phone" type="tel"></label><label>Current task (optional)<input name="task"></label>`}
if(a==='payment'||a==='expayment'){title='Add payment';f=amount('paid','Payment amount (ZMW)')}
if(a==='task'){title='Update task';f=input('task','Task','text',db.workers.find(w=>w.id===id).task||'')}
$('#formTitle').textContent=title;$('#fields').innerHTML=f;$('dialog').showModal()}
$('#add').onclick=()=>open({Overview:'sale',Sales:'sale',Stock:'stock','Animal health':'health',Expenses:'expense',Workers:'worker'}[page]);$('#close').onclick=()=>$('dialog').close();
$('#content').onclick=e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.action)open(d.action);if(d.pay)open('payment',d.pay);if(d.expay)open('expayment',d.expay);if(d.wage)open('wage',d.wage);if(d.task)open('task',d.task);if(d.attend){let n=structuredClone(db),w=n.workers.find(w=>w.id===d.attend);w.attendance=w.attendance||[];if(w.attendance.includes(today()))return toast('Already marked present today.');w.attendance.push(today());if(persist(n))toast('Attendance saved.')}if(d.done){let n=structuredClone(db);n.health.find(h=>h.id===d.done).done=true;persist(n)}};
$('#form').onsubmit=e=>{e.preventDefault();let r=Object.fromEntries(new FormData(e.target)),n=structuredClone(db);for(let k of ['qty','min','price','paid','amount'])if(k in r){r[k]=Number(r[k]);if(!Number.isFinite(r[k])||r[k]<0)return fail('Enter valid positive amounts.')}function fail(s){$('#error').textContent=s}r.id=crypto.randomUUID();
if(action==='stock'){if(n.stock.some(s=>s.name.toLowerCase()===r.name.trim().toLowerCase()))return fail('This item already exists. Use a stock movement.');r.name=r.name.trim();n.stock.push(r)}
if(action==='sale'){let s=n.stock.find(s=>s.id===r.stock);if(r.qty<=0||r.qty>s.qty)return fail('Quantity must be greater than zero and within available stock.');r.total=Math.round(r.qty*r.price*100)/100;if(r.paid>r.total)return fail('Payment cannot exceed the sale value.');s.qty=Math.round((s.qty-r.qty)*100)/100;r.product=s.name;n.sales.push(r)}
if(action==='movement'){let s=n.stock.find(s=>s.id===r.stock);if(r.qty<=0)return fail('Quantity must be greater than zero.');if(r.direction!=='Received'&&r.qty>s.qty)return fail('Not enough stock for this movement.');s.qty=Math.round((s.qty+(r.direction==='Received'?r.qty:-r.qty))*100)/100;n.movements=n.movements||[];n.movements.push({...r,date:today()})}
if(action==='expense'||action==='wage'){if(r.amount<=0||r.paid>r.amount)return fail('Enter an amount above zero; payment cannot exceed it.');if(action==='wage'){r.worker=target;r.category='Wages'}n.expenses.push(r)}
if(action==='health')n.health.push(r);if(action==='worker')n.workers.push({...r,attendance:[]});if(action==='task')n.workers.find(w=>w.id===target).task=r.task;
if(action==='payment'||action==='expayment'){let x=(action==='payment'?n.sales:n.expenses).find(s=>s.id===target),total=action==='payment'?x.total:x.amount;if(r.paid<=0||r.paid>Math.round((total-x.paid)*100)/100)return fail('Payment must be greater than zero and within the balance.');x.paid=Math.round((x.paid+r.paid)*100)/100;x.payments=x.payments||[];x.payments.push({date:today(),amount:r.paid})}
if(persist(n)){$('dialog').close();toast('Record saved on this device.')}};
$('#export').onclick=()=>{let blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),data:db},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='farm-manager-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#import').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{let b=JSON.parse(await file.text());if(b.version!==1||!b.data||!['stock','sales','health','expenses','workers'].every(k=>Array.isArray(b.data[k])))throw Error();for(let [key,fields]of Object.entries({stock:['qty','min'],sales:['qty','total','paid'],expenses:['amount','paid']}))for(let r of b.data[key])for(let f of fields)if(typeof r[f]!=='number'||!Number.isFinite(r[f])||r[f]<0)throw Error();if(confirm('Replace all records on this device with this backup? Export your current records first if needed.')){if(persist(b.data))toast('Backup restored.')}}catch{alert('This file is not a valid Farm Manager backup.')}e.target.value=''};
addEventListener('hashchange',render);render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
